Here is the extended C# code that maintains the existing functionality of printing the report summary and adds the capability to export the report in CSV format:

```csharp
using System;
using System.IO;
using System.Text;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional functionality: Export report in CSV format if requested
        if (exportCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(csvFilePath, false, Encoding.UTF8))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Write CSV content based on report data
                    // Assuming SummaryReport has a method or properties to expose data for CSV export
                    // This is a placeholder implementation; adjust based on actual SummaryReport structure
                    var reportData = report.GetReportData(); // Hypothetical method to get key-value pairs
                    foreach (var item in reportData)
                    {
                        writer.WriteLine($"{item.Key},{item.Value}");
                    }
                }

                Console.WriteLine($"Report exported to CSV: {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

// Placeholder class for SummaryReport to demonstrate usage
public class SummaryReport
{
    public override string ToString()
    {
        return "This is the summary report content.";
    }

    // Hypothetical method to retrieve report data for CSV export
    public System.Collections.Generic.Dictionary<string, string> GetReportData()
    {
        var data = new System.Collections.Generic.Dictionary<string, string>();
        data.Add("Title", "Sample Report");
        data.Add("Date", DateTime.Now.ToString("yyyy-MM-dd"));
        data.Add("Status", "Completed");
        return data;
    }
}
